                if (!fu_coswid_read_tag(pairs[i].key, &tag_id, error))
                        return FALSE;
                if (tag_id == FU_COSWID_TAG_FILE) {
                        if (!fu_coswid_parse_one_or_many(pairs[i].value,
                                                         fu_coswid_firmware_parse_file,
                                                         self, /* user_data */
                                                         error))
